WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_grass_b_set_var'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '设草量与草速', 'kp-grass-b-set-var', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "牛吃草基础设元"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "草是活的！草的初始量为Y，每天生长的速度为X。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“牧场上长满了牧草，每天草匀速生长。这片草可供 10 头牛吃 20 天，或者供 15 头牛吃 10 天。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "设每头牛每天吃草量为 1 份。不要设未知数去算牛的效率。未知数只留给草。"}]}, {"type": "katexBlock", "attrs": {"content": "Y = (N - X) \\times T"}}, {"type": "paragraph", "content": [{"type": "text", "text": "其中：Y 是原有草量，N 是牛的数量，X 是每天新长出的草量，T 是吃完的天数。"}]}]}$$ AS jsonb), NULL, '设草量与草速的核心考点与实战推导。', category_node.id, CAST('["数量关系", "牛吃草问题", "设草量与草速"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_grass_b_set_var", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
